"""Conservative tight atlases preserve every pixel of the old padded sprites."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib
source=(ROOT/'assets/game.js').read_bytes();sha=hashlib.sha256(source).hexdigest()
script=source.decode().replace('// SOURCE: 99-instrumentation.js',r'''
window.__spriteEnvelopeProbe=()=>{const legacy=item=>{const b=item.b,variant=b?(b.kind==='home'?b.id%120:b.id%24):0,c=document.createElement('canvas');c.width=256;c.height=320;const g=c.getContext('2d');g.translate(128,240);
 if(item.kind==='streetprop')streetProp(g,item.id%3);else if(item.kind==='tree')tree(g,0,0,item.id%11,.83);else{polygon(g,[point(-item.w*.4,-item.d*.4),point(item.w*.6,-item.d*.4),point(item.w*.9,item.d*.3),point(0,item.d*.7)],'#48523f30');architecture(g,b.kind==='worksite'||b.redevelopment?b:{...b,id:variant},item.w,item.d);parcelDetails(g,b,item.w,item.d);architecturalIdentity(g,b,item.w,item.d);}return c;};
 const items=displayItems.slice();for(let id=0;id<120;id++)items.push({kind:'building',id,b:{id,kind:'home',condition:100,owner:-1,firm:-1,hh:-1},x:0,y:0,w:1,d:1});for(const kind of Object.keys(types)){const [w,d]=LANDMARK_SIZE[kind]||[1,1];for(const condition of [40,70,100])items.push({kind:'building',id:17,b:{id:17,kind,condition,owner:-1,firm:-1,hh:-1},x:0,y:0,w,d});}for(let id=0;id<11;id++)items.push({kind:'tree',id,x:0,y:0,w:1,d:1});for(let id=0;id<3;id++)items.push({kind:'streetprop',id,x:0,y:0,w:1,d:1});
 const failures=[];let pixels=0;for(const item of items){const old=legacy(item),tight=spriteFor(item),reconstructed=document.createElement('canvas');reconstructed.width=256;reconstructed.height=320;const g=reconstructed.getContext('2d');g.drawImage(tight,128-tight.anchorX,240-tight.anchorY);const a=old.getContext('2d').getImageData(0,0,256,320).data,b=g.getImageData(0,0,256,320).data;let different=0;for(let i=0;i<a.length;i++)if(a[i]!==b[i])different++;if(different)failures.push({kind:item.b?.kind||item.kind,id:item.id,condition:item.b?.condition,different});pixels+=256*320;}
 const count=atlas.size,bytes=[...atlas.values()].reduce((n,c)=>n+c.width*c.height*4,0),oldBytes=count*256*320*4,accountingExact=bytes===atlasBytes;let clearsCleanly=true;for(let i=0;i<4;i++){applyPresentationOptions();clearsCleanly=clearsCleanly&&atlas.size===0&&atlasBytes===0;for(const item of items.slice(0,100))spriteFor(item);clearsCleanly=clearsCleanly&&atlasBytes===[...atlas.values()].reduce((n,c)=>n+c.width*c.height*4,0);}return {items:items.length,pixelsCompared:pixels,failures,atlas:count,bytes,oldBytes,savedFraction:1-bytes/oldBytes,accountingExact,clearsCleanly,bounded:bytes<=48*1024*1024};};
// SOURCE: 99-instrumentation.js''')
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':844,'height':390});p.set_content(html);p.add_script_tag(content=script);p.locator('#newTown').click();p.locator('#pause').click();p.evaluate('__townTest.reset("settlement",42)');p.evaluate('__townTest.step(90)');r=p.evaluate('__spriteEnvelopeProbe()');assert not r['failures'],r;assert r['savedFraction']>.6 and r['accountingExact'] and r['bounded'] and r['clearsCleanly'],r;b.close()
assert hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest()==sha
out=ROOT/'reports/development-working-river';out.mkdir(exist_ok=True);(out/'sprite-envelopes.json').write_text(json.dumps({'source_sha256':sha,**r},indent=2)+'\n');print('PASS exact pixel equivalence for old and tight sprite envelopes',r)
